// Semantic retrieval cue extraction from model-generated summaries and structured metadata.

import type { AgentMessage } from "@earendil-works/pi-agent-core";

/** Options for extracting retrieval cues from conversation segments. */
export interface ExtractCuesOptions {
	/** Message sequence to analyze. */
	messages: AgentMessage[];
	/** Optional segment summary (typically generated by the model). */
	summary?: string;
	/** Optional contextual metadata containing explicit tags or topics. */
	metadata?: Record<string, unknown>;
}

/**
 * Parse retrieval cues explicitly generated by the model in a summary section.
 * Expects a "## Retrieval Cues" section containing bullet items, numbered items, or comma-separated keys.
 */
export function parseRetrievalCuesFromSummary(summary: string | undefined): string[] {
	if (!summary) return [];

	const headingMatch = summary.match(
		/(?:^|\n)#+\s+Retrieval Cues[^\n]*\n([\s\S]*?)(?=\n#+\s+|\n---|\n<read-files>|\n<modified-files>|\[Archived Session Pointer|$)/i,
	);
	if (!headingMatch || !headingMatch[1]) return [];

	const section = headingMatch[1].trim();
	const cues: string[] = [];

	for (const rawLine of section.split("\n")) {
		const line = rawLine.trim();
		if (
			!line ||
			line.startsWith("[") ||
			line.startsWith("(") ||
			line.startsWith("<") ||
			line.toLowerCase().includes("(none)") ||
			line.toLowerCase().startsWith("note:")
		) {
			continue;
		}

		// Strip list prefix: "- cue", "* cue", "1. cue", "• cue"
		const stripped = line.replace(/^[-*•]\s+|\d+[.)]\s+/, "").trim();
		if (!stripped) continue;

		if (stripped.includes(",")) {
			for (const part of stripped.split(",")) {
				const cue = cleanCue(part);
				if (cue) cues.push(cue);
			}
		} else {
			const cue = cleanCue(stripped);
			if (cue) cues.push(cue);
		}
	}

	return deduplicate(cues).slice(0, 10);
}

/**
 * Extract retrieval cues from conversation messages, summary, and metadata.
 * Prioritizes the model's explicit "## Retrieval Cues" judgment in the summary,
 * then explicit metadata tags, falling back to structural and keyword extraction.
 */
export function extractDefaultCues(options: ExtractCuesOptions): string[] {
	// 1. Primary: The model's explicit semantic cues from the summary
	if (options.summary) {
		const modelCues = parseRetrievalCuesFromSummary(options.summary);
		if (modelCues.length > 0) {
			return modelCues;
		}
	}

	// 2. Caller-provided metadata (e.g. explicit tags or topics)
	const metadataCues = extractFromMetadata(options.metadata);
	if (metadataCues.length > 0) {
		return metadataCues;
	}

	// 3. Fallback: Extract code anchors and salient keywords from messages and summary
	const fallbackCues = new Set<string>();

	for (const msg of options.messages) {
		extractTokensFromMessage(msg, fallbackCues);
	}

	if (options.summary) {
		extractTokensFromText(options.summary, fallbackCues);
	}

	const cleaned = deduplicate(Array.from(fallbackCues));
	return cleaned.slice(0, 20);
}

function cleanCue(raw: string): string {
	return raw
		.replace(/^[`"']+|[`"']+$/g, "")
		.replace(/^\[+|]+$/g, "")
		.replace(/^[.*\-#]+\s*/, "")
		.trim()
		.toLowerCase();
}

function deduplicate(items: string[]): string[] {
	return Array.from(new Set(items.filter((item) => item.length > 0)));
}

function extractFromMetadata(metadata: Record<string, unknown> | undefined): string[] {
	if (!metadata) return [];
	const cues: string[] = [];

	const keys = ["cues", "tags", "topics", "keywords", "cue"];
	for (const key of keys) {
		const val = metadata[key];
		if (typeof val === "string") {
			const cleaned = cleanCue(val);
			if (cleaned) cues.push(cleaned);
		} else if (Array.isArray(val)) {
			for (const item of val) {
				if (typeof item === "string") {
					const cleaned = cleanCue(item);
					if (cleaned) cues.push(cleaned);
				}
			}
		}
	}

	return deduplicate(cues);
}

