function extractTokensFromText(text: string, cues: Set<string>): void {
	// Backticks
	const backticked = text.match(/`([^`]+)`/g);
	if (backticked) {
		for (const code of backticked) {
			const cleaned = cleanCue(code.slice(1, -1));
			if (cleaned.length > 1 && cleaned.length < 60) {
				cues.add(cleaned);
			}
		}
	}

	// Code-like identifiers containing /, ., _, -
	const codePatterns = text.match(/[\p{L}\p{N}_./-]+/gu);
	if (codePatterns) {
		for (const token of codePatterns) {
			const cleaned = token.replace(/^[./\-_]+|[./\-_]+$/g, "").toLowerCase();
			if (
				(cleaned.includes("/") || cleaned.includes(".") || cleaned.includes("_") || cleaned.includes("-")) &&
				cleaned.length >= 2 &&
				cleaned.length < 60
			) {
				cues.add(cleaned);
			}
		}
	}

	// Distinct words/numbers with length >= 2
	const words = text.match(/[\p{L}\p{N}]+/gu);
	if (words) {
		for (const word of words) {
			const lower = word.toLowerCase();
			if (lower.length >= 2 && !FALLBACK_IGNORE_WORDS.has(lower)) {
				cues.add(lower);
			}
		}
	}
}

function extractTokensFromMessage(msg: AgentMessage, cues: Set<string>): void {
	if (!("role" in msg)) return;

	if (msg.role === "assistant") {
		if (Array.isArray(msg.content)) {
			for (const part of msg.content) {
				if (part.type === "toolCall") {
					if (part.name) cues.add(cleanCue(part.name));
					if (part.arguments && typeof part.arguments === "object") {
						const args = part.arguments as Record<string, unknown>;
						for (const key of ["path", "file", "command", "query", "url"]) {
							const val = args[key];
							if (typeof val !== "string" || val.length <= 1 || val.length >= 80) continue;
							// A whole shell command is never a useful cue: it is a verbatim blob,
							// not a search key. Record the program name instead.
							if (key === "command") {
								const program = val.trim().split(/\s+/)[0];
								if (program) cues.add(cleanCue(program));
							} else {
								cues.add(cleanCue(val));
							}
						}
					}
				} else if (part.type === "text") {
					extractTokensFromText(part.text, cues);
				}
			}
		} else if (typeof msg.content === "string") {
			extractTokensFromText(msg.content, cues);
		}
	} else if (msg.role === "bashExecution") {
		const bash = msg as { command?: string };
		if (typeof bash.command === "string") {
			const cmd = bash.command.trim().split(/\s+/)[0];
			if (cmd) cues.add(cleanCue(cmd));
		}
	} else if (msg.role === "user") {
		const content = msg.content;
		if (typeof content === "string") {
			extractTokensFromText(content, cues);
		} else if (Array.isArray(content)) {
			for (const part of content) {
				if (part.type === "text") {
					extractTokensFromText(part.text, cues);
				}
			}
		}
	}
}
